INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (30000, 1, 0, 2, 24001, 35, 0, "", 15, 0, "");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40000, 100, 0, 8, 91002, 36, 0, "", 1, 0, "");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 1, 8, 91002, 37, 0, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 1, 107501, "ぺコリーヌ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 1, 8, 91002, 38, 0, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 2, 107601, "コッコロ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 1, 8, 91002, 39, 0, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 3, 107801, "キャル");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 1, 8, 91002, 40, 0, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 4, 107701, "スズメ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 1, 8, 91002, 41, 0, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 5, 107901, "タマキ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 2, 8, 91002, 42, 0, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 6, 107501, "ぺコリーヌ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 2, 8, 91002, 43, 0, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 7, 107601, "コッコロ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 2, 8, 91002, 44, 0, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 8, 107801, "キャル");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 2, 8, 91002, 45, 0, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 9, 107701, "スズメ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40001, 150, 2, 8, 91002, 46, 0, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 10, 107901, "タマキ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40003, 150, 0, 8, 91002, 57, 0, "", 1, 0, "");
