INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 1, 2, 24001, 321, 0, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 125801, "リリ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 1, 2, 24001, 322, 0, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2, 126001, "クリア");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 1, 2, 24001, 323, 0, "んーと。\nこれ、あげる。\nはい", 3, 126101, "プレシア");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 2, 2, 24001, 324, 0, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 4, 125801, "リリ");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 2, 2, 24001, 325, 0, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 5, 126001, "クリア");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (40011, 1, 2, 2, 24001, 326, 0, "お兄。\nきてくれて、うれしい", 6, 126101, "プレシア");
